// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // The deployer (address(this)) has wards = 1 initially.
        // Call rely on the deployer; in the reference it sets wards[address(this)] = 1 (no change),
        // but in the buggy version it sets wards[address(this)] = 0.
        // Then call allowance (any valid call) – the difference is observable via auth modifier.
        // Try a call that requires auth: updatePrice
        // In reference it succeeds, in buggy it reverts.
        vm.prank(address(this));
        c.rely(address(this));
        vm.prank(address(this));
        c.allowance(address(this), address(this));
        bool ok;
        try c.updatePrice(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

