    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deployer is already authed (wards[deployer] = 1)
        // In the buggy version, rely sets wards[user] = 0 instead of 1
        // So if deployer calls rely on himself, he loses auth and subsequent auth calls revert
        c.rely(address(this)); // In reference: keep auth; in buggy: revoke auth
        // Now try calling an auth-dependent function that should still work in reference
        bool ok;
        try c.mint(address(this), 100) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

